args.query:
SELECT SUM(vm.value) AS total_value_moments, SUM(ao.value) AS total_app_opens
FROM (
  SELECT value FROM (
    SELECT activity__active_date__day, value FROM query_metric('value_moments', time_grain => 'week', period => 'last_week')
  )
) vm JOIN (
  SELECT value FROM (
    SELECT activity__active_date__day, value FROM query_metric('app_opens', time_grain => 'week', period => 'last_week')
  )
) ao ON 1=1
